#!/usr/bin/perl
# usage: f.pl <startaddr-hex> [<endaddr-hex>]
my %M;
open(F,"/tmp/addrmap.txt");
while(<F>){chomp; my($a,$n)=split(/\t/,$_,2); $M{hex($a)}=$n;}
close F;
my $start=hex($ARGV[0]);
my $end = defined($ARGV[1])? hex($ARGV[1]) : 0;
open(D,"/tmp/dis_m.txt");
my $on=0;
while(<D>){
  if(/^([0-9a-f]+) </){ my $a=hex($1); $on = ($a==$start)?1:($on?0:0); if($a==$start){$on=1; my $nm=$M{$a}//""; print "=== $1 <$nm> ===\n"; next;} }
  if($on){
    if(/^\s*([0-9a-f]+):\s+(.*)$/){
      my ($a,$ins)=($1,$2);
      last if $end && hex($a)>=$end;
      $ins =~ s/<[^>]*>//g;
      # annotate call/jmp targets
      $ins =~ s/((?:call|jmp)\s+)([0-9a-f]+)\s*/"$1$2 <".($M{hex($2)}//"?").">"/e;
      printf "%s: %s\n",$a,$ins;
    } elsif(/^\s*$/){ last if !$end; }
  }
}
PERLEOF
